#include <bits/stdc++.h>
using namespace std;

bool validWord(const string& s, int maxLength) {
    if (s.empty() || (int)s.size() > maxLength) return false;
    for (char c : s) {
        if (!isalnum(static_cast<unsigned char>(c)) && c != '_')
            return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string id;
    cin >> id;

    size_t at = id.find('@');
    if (at == string::npos || id.find('@', at + 1) != string::npos) {
        cout << "NO";
        return 0;
    }

    size_t slash = id.find('/');
    if (slash != string::npos &&
        (slash < at || id.find('/', slash + 1) != string::npos)) {
        cout << "NO";
        return 0;
    }

    string username = id.substr(0, at);
    string hostname = id.substr(
        at + 1,
        (slash == string::npos ? id.size() : slash) - at - 1
    );

    if (!validWord(username, 16) ||
        hostname.empty() || hostname.size() > 32) {
        cout << "NO";
        return 0;
    }

    size_t start = 0;
    while (start <= hostname.size()) {
        size_t dot = hostname.find('.', start);
        string word = hostname.substr(
            start,
            dot == string::npos ? string::npos : dot - start
        );

        if (!validWord(word, 16)) {
            cout << "NO";
            return 0;
        }

        if (dot == string::npos) break;
        start = dot + 1;
    }

    if (slash != string::npos) {
        string resource = id.substr(slash + 1);
        if (!validWord(resource, 16)) {
            cout << "NO";
            return 0;
        }
    }

    cout << "YES";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool validChar(char c) {
    return (c >= 'A' && c <= 'Z') ||
           (c >= 'a' && c <= 'z') ||
           (c >= '0' && c <= '9') ||
           c == '_';
}

bool validPart(const string& s, int maxLength) {
    if (s.empty() || (int)s.size() > maxLength) return false;
    for (char c : s) {
        if (!validChar(c)) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string id;
    cin >> id;

    size_t at = id.find('@');
    if (at == string::npos || id.find('@', at + 1) != string::npos) {
        cout << "NO";
        return 0;
    }

    string user = id.substr(0, at);
    string remainder = id.substr(at + 1);

    if (!validPart(user, 16)) {
        cout << "NO";
        return 0;
    }

    size_t slash = remainder.find('/');
    if (slash != string::npos &&
        remainder.find('/', slash + 1) != string::npos) {
        cout << "NO";
        return 0;
    }

    string host = remainder.substr(0, slash);
    string resource = slash == string::npos
                    ? ""
                    : remainder.substr(slash + 1);

    if (host.empty() || host.size() > 32) {
        cout << "NO";
        return 0;
    }

    size_t start = 0;
    while (true) {
        size_t dot = host.find('.', start);
        string part = host.substr(start, dot == string::npos
                                       ? string::npos
                                       : dot - start);

        if (!validPart(part, 16)) {
            cout << "NO";
            return 0;
        }

        if (dot == string::npos) break;
        start = dot + 1;
    }

    if (slash != string::npos && !validPart(resource, 16)) {
        cout << "NO";
        return 0;
    }

    cout << "YES";
    return 0;
}

